using System.Text.Json;
using System.Text.Json.Nodes;
namespace RisingLands;
public static class ImprovementsV67Tests {
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: v67 "+name);Console.WriteLine("PASS: v67 "+name);}
 public static Simulation Fixture(string root,bool meal=true){
  var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(w);Array.Fill(w.Collision,(byte)0);Array.Fill(w.Tiles,(ushort)349);Array.Clear(w.Objects);Array.Clear(w.Quantities);Array.Clear(w.Resources);w.Resources[0]=20;
  var settler=w.Units.First(a=>a.Owner==0&&a.Type==9&&a.LegacyState==14);foreach(var ids in w.BuildingResidents.Values)ids.Remove(settler.Slot);var b=new Building(900,3,0,10+256*10);w.Buildings.Add(b);w.BuildingResidents[900]=new(){settler.Slot};
  if(meal){w.Objects[4+256*4]=67;w.Quantities[4+256*4]=3;}
  var farmer=w.Units.First(a=>a.Type==5&&a.Owner==0);farmer.X=3*1024;farmer.Y=4*1024;
  return new(w,new(){StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==3).Levels.ToArray(),SelectedBranch=0});
 }
 static void Until(Simulation s,Func<bool> condition,int limit=4000){for(int i=0;i<limit&&!condition();i++)s.Step();Check(condition(),"bounded integration completes");}
 public static void Run(string root){
  string path=Path.Combine(Path.GetTempPath(),"rising-audio-v67-"+Guid.NewGuid()+".json");try{var audio=new AudioSettings();audio.Volumes=new[]{50,60,70,80,90};audio.Muted[2]=true;audio.Save(path);var loaded=AudioSettings.Read(path);Check(loaded.Gain(2)==0&&Math.Abs(loaded.Gain(4)-.45f)<.0001,"audio preferences persist with independent mute and master gain");loaded.Muted[0]=true;Check(Enumerable.Range(1,4).All(i=>loaded.Gain(i)==0),"master mute silences every channel");File.WriteAllText(path,"{broken");Check(AudioSettings.Read(path).Volumes.Length==5,"invalid audio file recovers defaults");}finally{if(File.Exists(path))File.Delete(path);}
  var catalog=JsonSerializer.Deserialize<AudioCatalog>(File.ReadAllText(PackageLayout.FromBase("Content/Data/audio_catalog.json")),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;var clips=catalog.Clips.SelectMany(c=>c.Files??new[]{c.File}).Distinct().ToArray();Check(clips.Length==551&&clips.All(f=>File.Exists(PackageLayout.FromBase("Content/Data/Audio",f))),"all 551 original sound clips packaged");
  var s=Fixture(root);var a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);int ground=4+256*4;s.World.Quantities[ground]--;a.Food=1;a.CargoKind=1;a.Satiety=0;Check(s.Order(a,8,4),"loaded farmer receives route before hunger");s.Step();Check(s.Feeding(a)&&a.Food==1,"hunger pauses existing task without losing cargo");Until(s,()=>a.Satiety>0);Check(s.Hunger.Consumed[0]==1&&s.World.Resources[0]==20&&s.World.Quantities[ground]==1&&a.Food==1,"ground food is preferred to warehouse and cargo is preserved");Until(s,()=>a.Route.Count==0);Check(a.X==8*1024&&a.Y==4*1024,"original movement destination resumes after eating");var copy=Fixture(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"hunger reserve and consumption survive save/load");
  var invalid=JsonNode.Parse(s.Serialize())!;invalid["Hunger"]!["Consumed"]![0]=0;string before=s.Serialize();try{s.Restore(invalid.ToJsonString());throw new Exception("Invalid consumption accepted");}catch(InvalidDataException){}Check(s.Serialize()==before,"invalid hunger accounting is rejected atomically");
  s=Fixture(root,false);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);a.Satiety=0;s.Step();Until(s,()=>a.Satiety>0);Check(s.World.Resources[0]==19&&s.Hunger.Consumed[0]==1,"warehouse is used when ground food is absent");copy=Fixture(root,false);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"warehouse feeding remains conserved through saves");
  s=Fixture(root,false);Array.Clear(s.World.Resources);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);a.Satiety=0;a.FatigueClock=2999;int hp=a.Health;s.Order(a,8,4);s.Step();Check(a.Health==hp-20&&a.FatigueClock==1500&&s.Feeding(a),"starvation applies original 20 damage and half-period reset");a.Health=20;a.FatigueClock=2999;s.Step();Check(a.Health==0&&!s.Feeding(a)&&a.Route.Count==0,"starvation death cancels orders and feeding trip");
  s=Fixture(root);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);a.Satiety=1;a.FatigueClock=2999;s.Order(a,8,4);s.Step();Check(a.Satiety==0&&a.FatigueClock==0&&s.Feeding(a),"original reserve decrements at 3000 active updates");before=s.Serialize();copy=Fixture(root);copy.Restore(before);for(int i=0;i<100;i++){s.Step();copy.Step();}Check(s.Serialize()==copy.Serialize(),"active feeding trip resumes deterministically after reload");
  s=Fixture(root);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);s.AgricultureResearch.Index=14;Check(s.FatiguePeriod(a)==7500,"native agriculture fatigue bonus extends active interval to 7500 updates");s.AgricultureResearch.Index=18;Check(s.FatiguePeriod(a)==9000,"native final fatigue bonus extends active interval to 9000 updates");
  s=Fixture(root);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);a.Satiety=0;s.Step();Check(s.Feeding(a),"hungry farmer has pending meal");Check(s.GatherWarehouse(a,900)&&!s.Feeding(a)&&a.FoodSourceBuilding==900,"new warehouse order replaces paused task before the next feeding decision");
  s=Fixture(root);a=s.World.Units.First(a=>a.Type==5&&a.Owner==0);int drop=8+5*256;Check(s.Gather(a,ground)&&s.SetFoodDestination(a,1,drop),"farmer receives real ground collection and delivery loop");Until(s,()=>a.FoodJob==2);int cadence=a.WorkTicks;a.Satiety=0;s.Step();Until(s,()=>a.Satiety>0);Check(a.FoodJob==2&&a.WorkTicks<=cadence&&a.FoodSource==ground&&a.FoodDestination==drop,"feeding resumes collection source, destination and cadence");Until(s,()=>s.World.Quantities[drop]>0);Check(s.World.Objects[drop]==67&&s.Hunger.Consumed[0]==1,"resumed worker delivers remaining food without duplicating eaten food");copy=Fixture(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"resumed collection and meal accounting reload together");
  string saveDir=Path.Combine(Path.GetTempPath(),"rising-slots-v67-"+Guid.NewGuid());Directory.CreateDirectory(saveDir);try{string previous=Path.Combine(saveDir,"campaign.slot-1.research-v28.json");File.WriteAllText(previous,s.Serialize());string previousBytes=File.ReadAllText(previous);var slots=new SaveSlots(saveDir,s.World.MapName,shared:true);Check(slots.Existing(1)==previous&&slots.PathFor(1).EndsWith("research-v31.json"),"v29 save slots discover v28 files without replacing their name");slots.Save(s,1);Check(File.ReadAllText(previous)==previousBytes&&slots.Existing(1)==slots.PathFor(1),"saving new hunger state preserves previous-version save file");}finally{foreach(string f in Directory.GetFiles(saveDir))File.Delete(f);Directory.Delete(saveDir);}
  foreach(var shape in Enum.GetValues<FormationShape>()){
   var units=Enumerable.Range(0,48).Select(i=>new Actor{Slot=i,Type=i<3?2:i<25?8:0}).ToArray();var cells=TroopFormations.Positions(48,shape).Select(p=>128+p.X+256*(128+p.Y)).ToArray();var assigned=s.AssignFormationCells(units,cells);var leaders=units.Take(3).Select(a=>assigned[a.Slot]).ToArray();int covered=cells.Count(c=>leaders.Any(p=>ProjectileMath.WithinRange((p&255)-(c&255),(p>>8)-(c>>8),100)));int central=cells.Count(c=>ProjectileMath.WithinRange((cells[0]&255)-(c&255),(cells[0]>>8)-(c>>8),100));Check(assigned.Values.Distinct().Count()==48,"formation has unique destinations "+shape);Check(covered>=central,"captains cover at least the central cluster "+shape);Check(leaders.All(c=>Array.IndexOf(cells,c)<cells.Length*4/5),"captains avoid exposed outer band "+shape);var remaining=cells.Where(c=>!leaders.Contains(c)).ToArray();Check(units.Where(a=>a.Type==8).All(a=>Array.IndexOf(remaining,assigned[a.Slot])<22),"ranged units retain protected center "+shape);
  }
  Check(ResearchGame.UnitPortrait(25)==0x29e1,"Stomper uses original creature portrait");Check(Simulation.FoodData.Capacities[13]==5&&OriginalWorkerPolicy.Collects(13,1),"Reaper has native five-food load and collection policy");
  var native=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(native);s=new(native);for(int i=0;i<100;i++)s.Constructions.Add(new(){Id=2000+i,Type=3,Cell=5+i%20*5+256*(5+i/20*5),Progress=i%2==0?1:s.Rule(3).Duration});
  for(int c=0;c<65536;c++){bool expected=s.Constructions.Any(site=>Simulation.Inside(c,site.Cell,s.Rule(site.Type).Width,s.Rule(site.Type).Height));if(s.ConstructionCovers(c)!=expected)throw new Exception("Spatial footprint mismatch "+c);}Check(true,"spatial index matches all 65,536 construction footprint queries");
  Console.WriteLine("ALL IMPROVEMENTS v67 TESTS PASSED");
 }
}
